/* Float test   Byte Jul.87 p.104   typed by O.E.Tutzauer	*/#define CONST1 	3.141597E0#define CONST2	1.7839032E4#define COUNT	7000main()	{	double a,b,c;	int i;		a = CONST1;	b = CONST2;printf("start \n");	for (i=0; i<COUNT; ++i) 	{		c=a*b;		c=c/a;		c=a*b;		c=c/a;		c=a*b;		c=c/a;		c=a*b;		c=c/a;		c=a*b;		c=c/a;		c=a*b; 		c=c/a;		c=a*b; 		c=c/a;	}printf("%d loops done \n",COUNT );}